#include "About.h"

#include "BuildInfo.h"  // generated by cmake/build-info.cmake

#ifndef SCRIBLE_VERSION
#define SCRIBLE_VERSION "dev"
#endif

namespace scrible {

BuildInfo buildInfo() { return {SCRIBLE_VERSION, SCRIBLE_COMMIT, SCRIBLE_COMMIT_DATE}; }

std::vector<std::string> aboutText(const std::vector<std::string>& platform, const std::string& notebooksDir) {
    const BuildInfo b = buildInfo();
    std::vector<std::string> t = {"Handwritten notes for the Kindle Scribe, kept as Xournal++ .xopp files.", ""};
    if (!b.commit.empty()) t.push_back("Build " + b.commit + (b.date.empty() ? "" : " (" + b.date + ")"));
    t.insert(t.end(), platform.begin(), platform.end());
    if (!notebooksDir.empty()) t.push_back("Notebooks: " + notebooksDir);
    t.insert(t.end(), {"",
                       "Copyright (C) 2026 Sam Stratter. Free software under the GNU GPL, version 3 or later, "
                       "with no warranty; see LICENSE and THIRD-PARTY-NOTICES.md in the app's folder."});
    return t;
}

}  // namespace scrible
